import Foundation

@MainActor
enum LocalizedText {
    static func text(_ german: String, _ english: String) -> String {
        text(german, english, language: AppSettings.shared.appLanguage)
    }

    static func text(_ german: String, _ english: String, language: AppLanguage) -> String {
        switch language {
        case .german:
            return german
        case .english:
            return english
        case .traditionalChinese:
            let simplified = translations[english]?[.simplifiedChinese] ?? english
            return simplified.applyingTransform(StringTransform("Hans-Hant"), reverse: false) ?? simplified
        default:
            return translations[english]?[language] ?? english
        }
    }

    static func format(_ german: String, _ english: String, replacements: [String: String]) -> String {
        replacements.reduce(into: text(german, english)) { value, replacement in
            value = value.replacingOccurrences(of: "{\(replacement.key)}", with: replacement.value)
        }
    }

    static func matches(_ rendered: String, german: String, english: String) -> Bool {
        rendered == text(german, english)
    }

    static func status(_ rawValue: String?) -> String {
        guard let rawValue else { return text("Unbekannt", "Unknown") }
        if rawValue.localizedCaseInsensitiveContains("offline") {
            return text("Offline", "Offline")
        }
        if rawValue.localizedCaseInsensitiveContains("online") {
            return text("Online", "Online")
        }
        return rawValue
    }

    static func metricTitle(_ metric: BarMetric, short: Bool = false) -> String {
        let pair: (String, String) = switch (metric, short) {
        case (.battery, false): ("Batterie", "Battery")
        case (.battery, true): ("Akku", "Batt")
        case (.solar, _): ("PV", "PV")
        case (.home, false): ("Hauslast", "Home Load")
        case (.home, true): ("Last", "Load")
        case (.grid, false): ("Netzbezug", "Grid Import")
        case (.grid, true): ("Netz", "Grid")
        case (.batteryFlow, false): ("Akku-Fluss", "Battery Flow")
        case (.batteryFlow, true): ("Fluss", "Flow")
        case (.flow, false): ("Energiefluss", "Energy Flow")
        case (.flow, true): ("Flow", "Flow")
        case (.today, false): ("Heutiger Ertrag", "Today's Yield")
        case (.today, true): ("Ertrag", "Yield")
        case (.total, false): ("Gesamtertrag", "Total Yield")
        case (.total, true): ("Gesamt", "Total")
        case (.status, _): ("Status", "Status")
        }
        return text(pair.0, pair.1)
    }

    static func historyRangeTitle(_ range: HistoryRange, short: Bool = false) -> String {
        let pair: (String, String) = switch (range, short) {
        case (.current, false): ("Aktuell", "Current")
        case (.current, true): ("Akt.", "Now")
        case (.day, false): ("24 Stunden", "24 Hours")
        case (.day, true): ("24h", "24h")
        case (.week, false): ("7 Tage", "7 Days")
        case (.week, true): ("7T", "7d")
        case (.month, false): ("30 Tage", "30 Days")
        case (.month, true): ("30T", "30d")
        case (.custom, false): ("Individuell", "Custom")
        case (.custom, true): ("Eig.", "Custom")
        }
        return text(pair.0, pair.1)
    }

    static func relativeTime(_ value: Int, unit: RelativeTimeUnit) -> String {
        let pair: (String, String) = switch unit {
        case .seconds: ("vor \(value) Sekunden", "\(value) seconds ago")
        case .minutes: ("vor \(value) Minuten", "\(value) minutes ago")
        case .hours: ("vor \(value) Stunden", "\(value) hours ago")
        case .days: ("vor \(value) Tagen", "\(value) days ago")
        }
        let template = text(pair.0.replacingOccurrences(of: "\(value)", with: "{value}"), pair.1.replacingOccurrences(of: "\(value)", with: "{value}"))
        return template.replacingOccurrences(of: "{value}", with: String(value))
    }

    enum RelativeTimeUnit {
        case seconds, minutes, hours, days
    }

    private static let translationLanguages: [AppLanguage] = [
        .french, .spanish, .italian, .dutch, .polish, .portuguese,
        .czech, .danish, .swedish, .norwegian, .finnish, .russian,
        .simplifiedChinese, .japanese, .korean, .turkish, .romanian
    ]

