    """#

    private static let translations = makeTranslations()
    private static func makeTranslations() -> [String: [AppLanguage: String]] {
        var result: [String: [AppLanguage: String]] = [:]
        for line in translationTable.split(whereSeparator: \.isNewline) {
            let columns = line.split(separator: "\t", omittingEmptySubsequences: false).map(String.init)
            guard columns.count == translationLanguages.count + 1 else { continue }
            let key = columns[0]
            for (index, language) in translationLanguages.enumerated() {
                result[key, default: [:]][language] = columns[index + 1]
            }
        }
        return result
    }
